static String classifyGradleError(String msg) {
    if (msg.contains("Could not find")) return "DEPENDENCY";
    if (msg.contains("checksum") || msg.contains("tampered")) return "SECURITY/WRAPPER";
    if (msg.contains("toolchain") || msg.contains("Java installation")) return "JAVA_VERSION";
    if (msg.contains("workspace metadata")) return "CACHE";
    return "UNKNOWN";
}
