static List<String> diagnoseMultipleIssues(boolean slowBuild, boolean dependencyError, boolean staleDaemon) {
    List<String> actions = new ArrayList<>();
    if (staleDaemon) actions.add("1. ./gradlew --stop (najpierw wyczysc stan demona)");
    if (dependencyError) actions.add("2. Sprawdz literowke/repo zaleznosci");
    if (slowBuild) actions.add("3. Uruchom --profile, zeby znalezc waskie gardlo");
    return actions;
}
