static void detectPerformanceRegression(List<Long> times, double threshold) {
    List<Long> sorted = new ArrayList<>(times);
    Collections.sort(sorted);
    long median = sorted.get(sorted.size()/2);
    for (int i = 0; i < times.size(); i++) {
        if (times.get(i) > median * threshold) { System.out.println("Regresja wykryta w buildzie #" + (i+1) + ": " + times.get(i) + "ms"); return; }
    }
}
detectPerformanceRegression(List.of(100L,105L,98L,102L,99L,101L,500L,103L,97L,100L), 2.0);

static void calculateCacheEfficiency(Map<String,String> taskStatuses) {
    long efficient = taskStatuses.values().stream().filter(s -> s.equals("UP-TO-DATE") || s.equals("FROM-CACHE")).count();
    double pct = 100.0 * efficient / taskStatuses.size();
    String rating = pct > 70 ? "DOBRA" : (pct > 30 ? "SREDNIA" : "ZLA");
    System.out.println("Efektywnosc cache: " + pct + "% (" + rating + ")");
}

static boolean verifyChecksum(String expected, String actual) {
    if (!expected.equals(actual)) { System.out.println("BLAD: suma kontrolna niezgodna - dystrybucja mogla zostac zmanipulowana!"); return false; }
    System.out.println("OK: suma kontrolna zgodna");
    return true;
}
