verifyChecksum("abc123","xyz789");

static void diffConfigurations(Map<String,String> local, Map<String,String> ci) {
    Set<String> allKeys = new HashSet<>(local.keySet());
    allKeys.addAll(ci.keySet());
    for (String k : allKeys) {
        String l = local.getOrDefault(k, "BRAK");
        String c = ci.getOrDefault(k, "BRAK");
        if (!l.equals(c)) System.out.println(k + ": lokalnie=" + l + ", CI=" + c);
    }
}
diffConfigurations(Map.of("org.gradle.daemon","true"), Map.of("org.gradle.daemon","false"));

